using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.AspNetCore.Razor.TagHelpers;

namespace MyApp.CustomTagHelpers
{
    [HtmlTargetElement("div", Attributes = "panel-title")]
    public class PanelTagHelper : TagHelper
    {
        public string PanelTitle { get; set; }

        public override void Process(TagHelperContext context, TagHelperOutput output)
        {
            var header = new TagBuilder("div");
            header.Attributes["class"] = "panel-header bg-primary text-white p-2";
            header.InnerHtml.Append(PanelTitle);

            output.PreElement.SetHtmlContent(header);
            output.PostElement.SetHtmlContent("<hr />");
        }
    }
}

using Microsoft.AspNetCore.Razor.TagHelpers;

namespace MyApp.CustomTagHelpers
{
    [HtmlTargetElement("td", Attributes = "underline")]
    public class UnderlineTagHelper : TagHelper
    {
        public override void Process(TagHelperContext context, TagHelperOutput output)
        {
            output.PreContent.SetHtmlContent("<u>");
            output.PostContent.SetHtmlContent("</u>");
        }
    }
}

using Microsoft.AspNetCore.Razor.TagHelpers;

namespace MyApp.CustomTagHelpers
{
    [HtmlTargetElement("div", Attributes = "theme")]
    public class ParentThemeTagHelper : TagHelper
    {
        public string Theme { get; set; }
        public override void Process(TagHelperContext context, TagHelperOutput output)
        {
            context.Items["theme"] = Theme;
        }
    }

    [HtmlTargetElement("button", ParentTag = "div")]
    [HtmlTargetElement("a", ParentTag = "div")]
    public class ChildThemeTagHelper : TagHelper
    {
        public override void Process(TagHelperContext context, TagHelperOutput output)
        {
            if (context.Items.TryGetValue("theme", out var theme))
            {
                output.Attributes.SetAttribute("class", $"btn btn-{theme}");
            }
        }
    }
}

using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.AspNetCore.Razor.TagHelpers;

namespace MyApp.CustomTagHelpers
{
    [HtmlTargetElement("form")]
    public class SmartFormTagHelper : TagHelper
    {
        [ViewContext]
        [HtmlAttributeNotBound]
        public ViewContext ViewContext { get; set; }

        public override void Process(TagHelperContext context, TagHelperOutput output)
        {
            var routeData = ViewContext.RouteData.Values;
            var controller = routeData["controller"]?.ToString();
            var action = routeData["action"]?.ToString();
            output.Attributes.SetAttribute("action", $"/{controller}/{action}");
        }
    }
}

using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.AspNetCore.Razor.TagHelpers;

namespace MyApp.CustomTagHelpers
{
    [HtmlTargetElement(Attributes = "hide-on-action")]
    public class HideOnActionTagHelper : TagHelper
    {
        public string HideOnAction { get; set; }

        [ViewContext]
        [HtmlAttributeNotBound]
        public ViewContext ViewContext { get; set; }

        public override void Process(TagHelperContext context, TagHelperOutput output)
        {
            var currentAction = ViewContext.RouteData.Values["action"]?.ToString();
            if (currentAction == HideOnAction)
            {
                output.SuppressOutput();
            }
        }
    }
}

using Microsoft.AspNetCore.Razor.TagHelpers;

namespace MyApp.CustomTagHelpers
{
    [HtmlTargetElement("alert-box")]
    public class AlertBoxTagHelper : TagHelper
    {
        public string Type { get; set; } = "info";
        public override void Process(TagHelperContext context, TagHelperOutput output)
        {
            output.TagName = "div";
            output.TagMode = TagMode.StartTagAndEndTag;
            output.Attributes.SetAttribute("class", $"alert alert-{Type}");
            output.Attributes.SetAttribute("role", "alert");
        }
    }
}
